// Canvas Runner – simple endless runner
// Assumes an existing <canvas id="game"></canvas> in the HTML

(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return; // safety
  const ctx = canvas.getContext('2d');
  // Set a default size if not configured in HTML/CSS
  canvas.width = canvas.width || 800;
  canvas.height = canvas.height || 400;

  // ---------- Game objects ----------
  const player = {
    x: 50,
    y: 0,
    w: 30,
    h: 50,
    vy: 0,
    jumpForce: -12,
    grounded: false,
  };

  const obstacles = [];
  const obstacleSpeed = 4;
  let lastSpawn = 0;
  const spawnInterval = 1500; // ms

  let score = 0;
  let gameOver = false;

  // ---------- Utility ----------
  const rectsCollide = (a, b) =>
    a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;

  const jump = () => {
    if (player.grounded) {
      player.vy = player.jumpForce;
      player.grounded = false;
    }
  };

  // Input (mouse/touch or Space key)
  canvas.addEventListener('mousedown', jump);
  canvas.addEventListener('touchstart', e => { e.preventDefault(); jump(); });
  document.addEventListener('keydown', e => { if (e.code === 'Space') jump(); });

  // ---------- Game loop ----------
  const loop = timestamp => {
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#fff';
      ctx.font = '24px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`Game Over – Score: ${score}`, canvas.width / 2, canvas.height / 2);
      return;
    }
    requestAnimationFrame(loop);

    // Clear
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Player physics
    const gravity = 0.5;
    player.vy += gravity;
    player.y += player.vy;
    // Ground check
    const groundY = canvas.height - player.h;
    if (player.y > groundY) {
      player.y = groundY;
      player.vy = 0;
      player.grounded = true;
    }

    // Draw player
    ctx.fillStyle = '#0a74da';
    ctx.fillRect(player.x, player.y, player.w, player.h);

    // Spawn obstacles
    if (timestamp - lastSpawn > spawnInterval) {
      lastSpawn = timestamp;
      const height = 30 + Math.random() * 40; // 30‑70px tall
      obstacles.push({
        x: canvas.width,
        y: canvas.height - height,
        w: 20,
        h: height,
      });
    }

    // Update and draw obstacles
    ctx.fillStyle = '#c0392b';
    for (let i = obstacles.length - 1; i >= 0; i--) {
      const obs = obstacles[i];
      obs.x -= obstacleSpeed;
      ctx.fillRect(obs.x, obs.y, obs.w, obs.h);

      // Collision
      if (rectsCollide(player, obs)) {
        gameOver = true;
      }

      // Remove off‑screen obstacles and increase score
      if (obs.x + obs.w < 0) {
        obstacles.splice(i, 1);
        score++;
      }
    }

    // Draw score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText(`Score: ${score}` , 10, 20);
  };

  requestAnimationFrame(loop);
})();
